export function searchCuratedWorks(query: string): SearchResultItem[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const tokens = q.split(/\s+/).filter(Boolean);

  const scored: Array<{ work: CuratedMediaWork; score: number }> = [];

  for (const w of CURATED_WORKS) {
    const titleLower = w.title.toLowerCase();
    const aliasesLower = (w.aliases || []).map((a) => a.toLowerCase());
    const dirLower = (w.directorOrCreator || "").toLowerCase();
    const descLower = w.description.toLowerCase();
    const castNames = w.cast.map((c) => c.name.toLowerCase()).join(" ");
    const haystack = `${titleLower} ${aliasesLower.join(" ")} ${dirLower} ${w.releaseYear || ""} ${descLower} ${castNames}`;

    let score = 0;
    if (titleLower === q || aliasesLower.some((a) => a === q)) {
      score += 100;
    } else if (titleLower.startsWith(q) || aliasesLower.some((a) => a.startsWith(q))) {
      score += 75;
    } else if (titleLower.includes(q) || aliasesLower.some((a) => a.includes(q))) {
      score += 55;
    } else if (tokens.every((t) => haystack.includes(t))) {
      score += 35;
    } else if (tokens.length > 1 && tokens.filter((t) => t.length > 2 && titleLower.includes(t)).length >= 1) {
      score += 20;
    }

    if (score > 0) {
      scored.push({ work: w, score });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  return scored.map(({ work: w }) => ({
    id: w.id,
    wikidataId: w.wikidataId,
    title: w.title,
    releaseYear: w.releaseYear,
    endYear: w.endYear,
    mediaType: w.mediaType,
    description: w.description,
    posterUrl: w.posterUrl,
    castCountHint: w.cast.length,
    source: "curated",
  }));
}
